options.beforeRender:
if (data && Array.isArray(data)) {
  data.forEach(function(row) {
    var liveVal = null;
    var baseVal = null;
    var contribVal = null;

    if (row['Value #B'] != null) {
      liveVal = Number(row['Value #B']);
      baseVal = row['Value #B_base'] != null ? Number(row['Value #B_base']) : (row.BaselineVal ? Number(row.BaselineVal) : null);
      contribVal = row['Value #B_contrib'] != null ? Number(row['Value #B_contrib']) : null;
    } else if (row['Value #A'] != null) {
      liveVal = Number(row['Value #A']);
      baseVal = row['Value #A_base'] != null ? Number(row['Value #A_base']) : (row.BaselineVal ? Number(row.BaselineVal) : null);
      contribVal = row['Value #A_contrib'] != null ? Number(row['Value #A_contrib']) : null;
    } else if (row['Value #C'] != null) {
      liveVal = Number(row['Value #C']);
      baseVal = row['Value #C_base'] != null ? Number(row['Value #C_base']) : (row.BaselineVal ? Number(row.BaselineVal) : null);
      contribVal = row['Value #C_contrib'] != null ? Number(row['Value #C_contrib']) : null;
    } else if (row['Value #D'] != null) {
      liveVal = Number(row['Value #D']);
    } else if (row['Value #E'] != null) {
      liveVal = Number(row['Value #E']);
    } else if (row['Value #F'] != null) {
      liveVal = Number(row['Value #F']);
    } else if (row['Value #G'] != null) {
      liveVal = Number(row['Value #G']);
    } else if (row.Value != null) {
      liveVal = Number(row.Value);
      baseVal = row.BaselineVal ? Number(row.BaselineVal) : null;
    }

    if (baseVal != null && !isNaN(baseVal) && baseVal > 0) {
      row.DynamicBaseline = baseVal.toFixed(1) + (row.MetricUnit || 'ms');
      if (liveVal != null && !isNaN(liveVal) && liveVal > 0) {
        var ratio = liveVal / baseVal;
        row.DynamicDeviation = ratio.toFixed(1) + '× baseline';
      }
    } else {
      row.DynamicBaseline = row.BaselineText || '0.0%';
      row.DynamicDeviation = row.Deviation || 'Elevated';
    }

    if (contribVal != null && !isNaN(contribVal) && contribVal > 0) {
      row.DynamicContrib = contribVal.toFixed(0) + '%';
    } else {
      row.DynamicContrib = row.ContributionText || '100%';
    }
  });
}

options.styles:
.tn-cards-container {
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  width: 100%;
  box-sizing: border-box;
  padding: 2px 0;
  overflow: hidden;
}

.tn-card {
  flex: 1 1 340px;
  border-radius: 10px;
  padding: 14px 18px;
  box-sizing: border-box;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.4);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.tn-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.6);
}

.tn-card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 8px;
}

.tn-badge-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tn-icon-circle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  font-size: 10px;
  font-weight: 800;
}

.tn-severity-title {
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.tn-severity-pill {
  font-size: 10.5px;
  font-weight: 600;
  padding: 1px 7px;
  border-radius: 9999px;
  text-transform: capitalize;
}

.tn-metric-callout {
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.tn-headline {
  font-size: 14.5px;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 3px;
  line-height: 1.25;
}

.tn-description {
  font-size: 12px;
  color: #94a3b8;
  margin-bottom: 10px;
  line-height: 1.35;
}

.tn-meta-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 10px;
  margin-bottom: 10px;
}

.tn-meta-col {
  display: flex;
  flex-direction: column;
}

.tn-meta-label {
  font-size: 10px;
  text-transform: uppercase;
  font-weight: 600;
  color: #64748b;
  margin-bottom: 2px;
  display: flex;
  align-items: center;
  gap: 4px;
}

.tn-meta-val {
  font-size: 12px;
  font-weight: 600;
  color: #f1f5f9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tn-meta-sub {
  font-size: 11px;
  color: #64748b;
  margin-top: 1px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tn-action-row {
  display: flex;
  justify-content: flex-end;
  margin-top: auto;
}

.tn-action-btn {
  display: inline-flex;
  align-items: center;
  padding: 4px 12px;
  border-radius: 6px;
  font-size: 11.5px;
  font-weight: 600;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.03);
  transition: all 0.2s ease;
}

.tn-action-btn:hover {
  background: rgba(255, 255, 255, 0.1);
}

.tn-healthy-banner {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  border-radius: 10px;
  border: 1px solid rgba(16, 185, 129, 0.35);
  background: linear-gradient(180deg, rgba(16, 185, 129, 0.08) 0%, rgba(15, 23, 42, 0.4) 100%);
  width: 100%;
  box-sizing: border-box;
}

.tn-healthy-icon {
  font-size: 28px;
}

.tn-healthy-title {
  font-size: 16px;
  font-weight: 700;
  color: #10b981;
  margin-bottom: 2px;
}

.tn-healthy-sub {
  font-size: 13px;
  color: #94a3b8;
}
